<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/functions.php';
$pdo = getDbConnection(); $error = null;
if (empty($_SESSION['password_reset_user_id']) || empty($_SESSION['password_reset_verified']) || ($_SESSION['password_reset_expires'] ?? 0) < time()) { header('Location: ' . baseUrl('forgot-password.php')); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { enforceCsrf(); $password = $_POST['new_password'] ?? ''; $confirm = $_POST['confirm_password'] ?? ''; if (strlen($password) < 8 || $password !== $confirm) $error = 'Passwords must match and be at least 8 characters.'; else { $stmt = $pdo->prepare('UPDATE users SET password_hash = :hash WHERE user_id = :uid'); $stmt->execute([':hash' => password_hash($password, PASSWORD_DEFAULT), ':uid' => $_SESSION['password_reset_user_id']]); $pdo->prepare("UPDATE otp_verifications SET is_used = 1 WHERE otp_id = :oid AND purpose = 'password_reset'")->execute([':oid' => $_SESSION['password_reset_otp_id']]); unset($_SESSION['password_reset_user_id'], $_SESSION['password_reset_otp_id'], $_SESSION['password_reset_expires'], $_SESSION['password_reset_verified']); session_regenerate_id(true); setFlash('success', 'Password reset successfully. Please log in.'); header('Location: ' . baseUrl('login.php')); exit; } }
?><!DOCTYPE html><html><body><h2>Reset Password</h2><?php if ($error): ?><p><?= e($error) ?></p><?php endif; ?><form method="post"><?= csrfField() ?><input type="password" name="new_password" minlength="8" required><input type="password" name="confirm_password" minlength="8" required><button type="submit">Reset Password</button></form></body></html>
